import React, { useState } from "react";
import { useFormik } from "formik";
import * as Yup from 'yup'

const input = {
    name: '',
    email: '',
    no: '',
    add: '',
    city: '',
    gender: ''

}

const validate = Yup.object({
    name: Yup.string().min(2).max(100).required("plz enter your first first name"),
    email: Yup.string().email().required('Plz enter your email')
})

function Form() {
    const [getdata, setgetdata] = useState(input)

    const { values, errors, touched, handleBlur, handleChange, handleSubmit } = useFormik({
        initialValues: input,
        validationSchema: validate,
        onSubmit: async (values) => {
            try {
                const res = await fetch('http://localhost:7000/register', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(values)

                });
                const data = await res.json();
                console.log(data);
                if (res.ok) {
                    alert('registered successfully');
                }
                else {
                    alert('registration failed');
                }
            }
            catch (err) {
                console.log(err);
                alert("server error");
            }
        }
        })
    
    return (
        <main className="student-page">
            <section className="student-form-shell" aria-labelledby="student-form-title">
                <p className="student-kicker">STUDENT REGISTRATION</p>
                <h1 id="student-form-title">Student Form</h1>
                <form className="student-form" onSubmit={handleSubmit}>
                <div className="form-field">
                    <label htmlFor="student-name">Student name</label>
                    <input id="student-name" type="text" name="name" value={values.name} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.name && touched.name) && <span className="field-error">{errors.name}</span>}
                </div>
                <div className="form-field">
                    <label htmlFor="student-email">Email</label>
                    <input id="student-email" type="text" name="email" value={values.email} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.email && touched.email) && <span className="field-error">{errors.email}</span>}
                </div>
                <div className="form-field">
                    <label htmlFor="student-phone">Phone number</label>
                    <input id="student-phone" type="text" name="no" value={values.no} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.no && touched.no) && <span className="field-error">{errors.no}</span>}
                </div>

                <div className="form-field">
                    <label htmlFor="student-address">Address</label>
                    <input id="student-address" type="text" name="add" value={values.add} onChange={handleChange} onBlur={handleBlur} />
                    {(errors.add && touched.add) && <span className="field-error">{errors.add}</span>}
                </div>
                <div className="form-field">
                    <label htmlFor="student-city">City</label>
                    <select id="student-city" name='city' value={values.city} onChange={handleChange} onBlur={handleBlur} >
                        <option value=''>Select City</option>
                        <option value='Surat'>Surat</option>
                        <option value='Vapi'>Vapi</option>
                        <option value='Valsad'>Valsad</option>
                        <option value='Navsari'>Navsari</option>
                        <option value='Baroda'>Baroda</option>
                    </select>

                </div>
                <fieldset className="form-field gender-field">
                    <legend>Gender</legend>
                    <div className="gender-options">
                        <label className="gender-option">
                            <input type="radio" name="gender" value='male' onChange={handleChange} onBlur={handleBlur} />
                            <span>Male</span>
                        </label>
                        <label className="gender-option">
                            <input type="radio" name="gender" value='Female' onChange={handleChange} onBlur={handleBlur} />
                            <span>Female</span>
                        </label>
                    </div>
                </fieldset>
                <div className="form-actions">
                    <button type="submit">Submit registration <span aria-hidden="true">→</span></button>
                </div>
            </form>
            </section>
        </main>
    )

}
export default Form
